// ============================================================================
// n8n CODE NODE: Stage 1 JSON Parser
// ============================================================================
// 
// SETUP:
// 1. Add a "Code" node after your Stage 1 LLM node
// 2. Paste this entire code into the node
// 3. Connect input from: Stage 1 LLM output node
// 4. In Mode: select "Run Once for All Items" 
// 5. Expected input: items[0].json.output (raw model output)
//
// OUTPUT:
// Returns JSON with: success (bool), plan (object), validation (object), or error
// ============================================================================

// Get the raw output from the previous node
const rawOutput = $input.first().json.output;

if (!rawOutput) {
  throw new Error('❌ No output from Stage 1. Expected json.output field.');
}

// Ensure we have a string
let jsonString = typeof rawOutput === 'string' ? rawOutput : String(rawOutput);
jsonString = jsonString.trim();

// Remove markdown code blocks if present
jsonString = jsonString.replace(/^```(?:json)?\n?/, '');
jsonString = jsonString.replace(/\n?```$/, '');
jsonString = jsonString.replace(/^```\n?/, '');
jsonString = jsonString.replace(/\n?```$/, '');
jsonString = jsonString.trim();

// Find JSON object boundaries
const jsonStart = jsonString.indexOf('{');
const jsonEnd = jsonString.lastIndexOf('}');

if (jsonStart === -1 || jsonEnd === -1) {
  throw new Error('❌ No JSON object found in output (no { or })');
}

if (jsonStart > 0) {
  console.warn(`⚠️  Found ${jsonStart} characters before opening brace. Trimming.`);
}

if (jsonEnd < jsonString.length - 1) {
  console.warn(`⚠️  Found ${jsonString.length - jsonEnd - 1} characters after closing brace. Trimming.`);
}

// Extract JSON substring
jsonString = jsonString.substring(jsonStart, jsonEnd + 1);

// Parse JSON
let plan;
try {
  plan = JSON.parse(jsonString);
} catch (parseError) {
  throw new Error(`❌ Invalid JSON: ${parseError.message}`);
}

// === VALIDATION ===

// Check required fields
if (!plan.buildingRequest) {
  throw new Error('❌ Missing required field: buildingRequest');
}

if (!plan.stages || typeof plan.stages !== 'object' || Array.isArray(plan.stages)) {
  throw new Error('❌ Invalid stages structure: must be object with numeric string keys');
}

if (!plan.metadata) {
  throw new Error('❌ Missing required field: metadata');
}

if (!plan.workerCount) {
  throw new Error('❌ Missing required field: workerCount');
}

// Validate stages are sequential
const stageKeys = Object.keys(plan.stages)
  .map(k => parseInt(k))
  .sort((a, b) => a - b);

const expectedSequence = Array.from(
  { length: Math.max(...stageKeys) },
  (_, i) => i + 1
);

if (JSON.stringify(stageKeys) !== JSON.stringify(expectedSequence)) {
  throw new Error(`❌ Stages not sequential. Found: [${stageKeys}], Expected: [${expectedSequence}]`);
}

// Validate workers exist in all stages
const expectedWorkerCount = plan.workerCount;
for (let stageNum of stageKeys) {
  const stage = plan.stages[stageNum.toString()];
  const workersInStage = Object.keys(stage.tasks || {}).filter(k => k.startsWith('Worker')).length;

  if (workersInStage !== expectedWorkerCount) {
    throw new Error(
      `❌ Stage ${stageNum} has ${workersInStage} workers, expected ${expectedWorkerCount}`
    );
  }
}

// Validate coordinates in all tasks
for (let stageNum of stageKeys) {
  const stage = plan.stages[stageNum.toString()];
  const tasks = stage.tasks || {};

  for (let workerNum = 1; workerNum <= expectedWorkerCount; workerNum++) {
    const worker = tasks[`Worker${workerNum}`];

    if (!worker) continue;
    if (!worker.subtask || worker.subtask === 'rest') continue;

    if (!worker.coordinates) {
      throw new Error(`❌ Stage ${stageNum} Worker${workerNum} missing coordinates`);
    }

    const requiredCoords = ['xMin', 'xMax', 'yMin', 'yMax', 'zMin', 'zMax'];
    for (let coord of requiredCoords) {
      if (worker.coordinates[coord] === undefined) {
        throw new Error(
          `❌ Stage ${stageNum} Worker${workerNum} missing coordinate: ${coord}`
        );
      }
      if (typeof worker.coordinates[coord] !== 'number') {
        throw new Error(
          `❌ Stage ${stageNum} Worker${workerNum} ${coord} must be number, got ${typeof worker.coordinates[coord]}`
        );
      }
    }
  }
}

// === SUCCESS ===
console.log('✅ Stage 1 plan parsed successfully');
console.log(`   Stages: ${stageKeys.length}`);
console.log(`   Workers: ${expectedWorkerCount}`);
console.log(`   Building: ${plan.buildingRequest}`);

// Return parsed plan
return {
  success: true,
  plan: plan,
  validation: {
    stageCount: stageKeys.length,
    workerCount: expectedWorkerCount,
    stagesPerWorker: stageKeys.length / expectedWorkerCount,
    totalWorkerTasks: stageKeys.length * expectedWorkerCount
  }
};

